import { BytesReaderFactory } from "../io/ReaderFactory.js";

const VERSION = "GisWordBook/0";
const CHUNK_NAMES = ["GW00", "TM00", "TT00", "TI00"];
const PALETTE_SIZE = 15;
const textDecoder = new TextDecoder("utf-8");

/** GisWordBook/0 reader without persistent page or hierarchical indexes. */
export class GaluchatGisWordBookReader {
  constructor(readerFactory, sourceSize, options = {}) {
    this.readerFactory = readerFactory;
    this.tokenCacheSize = options.tokenCacheSize ?? 64;
    if (!Number.isInteger(this.tokenCacheSize) || this.tokenCacheSize < 0) {
      throw new RangeError("tokenCacheSize must be a non-negative integer");
    }
    this.tokenCache = new Map();
    const [headerChunk, tokenChunk, textChunk, indexChunk] = readChunkLayout(readerFactory, sourceSize);
    this.tokenChunk = tokenChunk;
    this.textChunk = textChunk;
    this.indexChunk = indexChunk;

    this.header = withReader(readerFactory, headerChunk.dataStart,
      (reader) => readHeader(reader, headerChunk.size));
    this.tokenCount = withReader(readerFactory, tokenChunk.dataStart,
      (reader) => new TokenMapReader(reader).tokenCount);
    const textHeader = withReader(readerFactory, textChunk.dataStart,
      (reader) => {
        const textReader = new TextTableReader(reader);
        return { recordCount: textReader.recordCount, tokenBits: textReader.tokenBits };
      });
    const indexHeader = withReader(readerFactory, indexChunk.dataStart,
      (reader) => new HierarchicalIndexReader(reader, indexChunk.size));
    if (textHeader.tokenBits < requiredBits(this.tokenCount)) {
      throw new Error("TT00 token_bits is smaller than TM00 token table requires");
    }
    if (indexHeader.codeBits < requiredBits(textHeader.recordCount)) {
      throw new Error("TI00 code_bits is smaller than TT00 text table requires");
    }
    this._componentCount = textHeader.recordCount;
    this._recordCount = indexHeader.recordCount;
    this._depth = indexHeader.maxDepth;
    this.codeBuffer = new Array(this._depth).fill(0);
  }

  static fromUint8Array(bytes, options = {}) {
    if (!(bytes instanceof Uint8Array)) {
      throw new TypeError("GaluchatGisWordBookReader requires Uint8Array");
    }
    return new GaluchatGisWordBookReader(new BytesReaderFactory(bytes), bytes.length, options);
  }

  get recordCount() { return this._recordCount; }
  get depth() { return this._depth; }
  get componentCount() { return this._componentCount; }

  readCodeSet(index, out = null) {
    return withReader(this.readerFactory, this.indexChunk.dataStart,
      (reader) => new HierarchicalIndexReader(reader, this.indexChunk.size).readCodeSet(index, out));
  }

  readComponentBytes(code) {
    return this.readComponentByteSets([code]).get(code);
  }

  readComponent(code) {
    return textDecoder.decode(this.readComponentBytes(code));
  }

  readStringSet(index, out = null) {
    const codes = this.readCodeSet(index, this.codeBuffer);
    const components = this.readComponentByteSets(codes);
    const result = out ?? [];
    result.length = 0;
    for (const code of codes) result.push(textDecoder.decode(components.get(code)));
    return result;
  }

  readStringSetByCode(code, out = null) {
    if (code === null || code <= 0) return null;
    return this.readStringSet(code - 1, out);
  }

  readComponentByteSets(codes) {
    const uniqueCodes = [...new Set(codes)].sort((a, b) => a - b);
    const tokenIdsByCode = withReader(this.readerFactory, this.textChunk.dataStart,
      (reader) => new TextTableReader(reader).readTokenIdSets(uniqueCodes));
    const tokenIds = [...new Set([...tokenIdsByCode.values()].flat())].sort((a, b) => a - b);
    const resolved = new Map();
    const missing = [];
    for (const tokenId of tokenIds) {
      if (this.tokenCache.has(tokenId)) {
        const token = this.tokenCache.get(tokenId);
        this.tokenCache.delete(tokenId);
        this.tokenCache.set(tokenId, token);
        resolved.set(tokenId, token);
      } else {
        missing.push(tokenId);
      }
    }
    if (missing.length > 0) {
      const loaded = withReader(this.readerFactory, this.tokenChunk.dataStart,
        (reader) => new TokenMapReader(reader).readTokens(missing));
      for (const [tokenId, token] of loaded) resolved.set(tokenId, token);
    }
    const results = new Map();
    for (const code of uniqueCodes) {
      const tokens = tokenIdsByCode.get(code).map((tokenId) => {
        const token = resolved.get(tokenId);
        this.rememberToken(tokenId, token);
        return token;
      });
      results.set(code, concatBytes(tokens));
    }
    return results;
  }

  rememberToken(tokenId, token) {
    if (this.tokenCacheSize === 0) return;
    this.tokenCache.delete(tokenId);
    this.tokenCache.set(tokenId, token);
    while (this.tokenCache.size > this.tokenCacheSize) {
      this.tokenCache.delete(this.tokenCache.keys().next().value);
    }
  }
}

class TokenMapReader {
  constructor(reader) {
    this.reader = reader;
    this.tokenCount = reader.readMbUInt();
    this.pageCount = reader.readMbUInt();
  }

  readTokens(targets) {
    const results = new Map();
    let targetPos = 0;
    let tokenBase = 0;
    let previousSize = -1;
    for (let page = 0; page < this.pageCount; page++) {
      if (this.reader.readByte() !== 0) throw new Error("unsupported TM00 PageHeader");
      const tokenSize = this.reader.readMbUInt();
      const pageTokens = this.reader.readMbUInt();
      const streamSize = this.reader.readMbUInt();
      validateTokenPage(tokenSize, pageTokens, streamSize, previousSize);
      previousSize = tokenSize;
      const pageEnd = tokenBase + pageTokens;
      let consumed = 0;
      while (targetPos < targets.length && targets[targetPos] < pageEnd) {
        const tokenId = targets[targetPos];
        if (tokenId < tokenBase || tokenId < 0 || tokenId >= this.tokenCount) {
          throw new RangeError("TM00 token id out of range");
        }
        const offset = (tokenId - tokenBase) * tokenSize;
        this.reader.skipInByte(offset - consumed);
        results.set(tokenId, this.reader.readAsBytes(tokenSize));
        consumed = offset + tokenSize;
        targetPos++;
      }
      if (targetPos === targets.length) return results;
      this.reader.skipInByte(streamSize - consumed);
      tokenBase = pageEnd;
    }
    throw new RangeError("TM00 token id out of range");
  }
}

class TextTableReader {
  constructor(reader) {
    this.reader = reader;
    this.recordCount = reader.readMbUInt();
    reader.readMbUInt();
    this.pageCount = reader.readMbUInt();
    this.tokenBits = reader.readMbUInt();
    if (this.tokenBits < 1 || this.tokenBits > 16) throw new Error("invalid TT00 token_bits");
  }

  readTokenIdSets(codes) {
    for (const code of codes) {
      if (!Number.isInteger(code) || code < 0 || code >= this.recordCount) {
        throw new RangeError("TT00 record code out of range");
      }
    }
    const results = new Map();
    let targetPos = 0;
    let recordBase = 0;
    let previousTokens = -1;
    for (let page = 0; page < this.pageCount; page++) {
      if (this.reader.readByte() !== 0) throw new Error("unsupported TT00 PageHeader");
      const recordTokens = this.reader.readMbUInt();
      const pageRecords = this.reader.readMbUInt();
      const streamSize = this.reader.readMbUInt();
      validateTextPage(recordTokens, pageRecords, previousTokens);
      previousTokens = recordTokens;
      const pageEnd = recordBase + pageRecords;
      const targetStart = targetPos;
      while (targetPos < codes.length && codes[targetPos] < pageEnd) targetPos++;
      if (targetStart === targetPos) {
        this.reader.skipInByte(streamSize);
        recordBase = pageEnd;
        continue;
      }
      const localTargets = codes.slice(targetStart, targetPos).map((code) => code - recordBase);
      const streamStart = bitPosition(this.reader);
      const local = decodeTargets(this.reader, pageRecords, localTargets, this.tokenBits);
      for (const [localCode, tokenIds] of local) {
        if (tokenIds.length !== recordTokens) throw new Error("TT00 record token count mismatch");
        results.set(recordBase + localCode, tokenIds);
      }
      if (targetPos === codes.length) return results;
      this.reader.skipBits(streamSize * 8 - (bitPosition(this.reader) - streamStart));
      recordBase = pageEnd;
    }
    throw new RangeError("TT00 record code out of range");
  }
}

class HierarchicalIndexReader {
  constructor(reader, size) {
    this.reader = reader;
    const start = reader.pos;
    this.maxDepth = reader.readMbUInt();
    this.recordCount = reader.readMbUInt();
    this.codeBits = reader.readMbUInt();
    this.rootCount = reader.readMbUInt();
    this.streamSize = reader.readMbUInt();
    validateIndexHeader(
      this.maxDepth,
      this.recordCount,
      this.codeBits,
      this.rootCount,
      this.streamSize,
    );
    if (reader.pos - start + this.streamSize !== size) throw new Error("TI00 has trailing bytes");
  }

  readCodeSet(index, out = null) {
    if (!Number.isInteger(index) || index < 0 || index >= this.recordCount) {
      throw new RangeError("TI00 index out of range");
    }
    const result = out ?? new Array(this.maxDepth);
    while (result.length < this.maxDepth) result.push(0);
    result.length = this.maxDepth;
    if (this.maxDepth === 1) this.readLeafBlocksByCount(this.rootCount, index, result);
    else this.readPrefixesByCount(0, this.rootCount, index, result);
    return result;
  }

  readPrefixesByCount(depth, count, target, out) {
    for (let index = 0; index < count; index++) {
      const code = this.reader.readBitsAsInt32(this.codeBits);
      const leaves = this.reader.readMbUInt();
      const payloadBits = this.reader.readMbUInt();
      if (target < leaves) {
        out[depth] = code;
        this.readChildren(depth + 1, leaves, target, out);
        return;
      }
      this.skipPayload(depth + 1, leaves, payloadBits);
      target -= leaves;
    }
    throw new RangeError("TI00 index not found");
  }

  readChildren(depth, leaves, target, out) {
    if (depth === this.maxDepth - 1) {
      this.readLeafBlocksByLeafCount(leaves, target, out);
      return;
    }
    let consumed = 0;
    while (consumed < leaves) {
      const code = this.reader.readBitsAsInt32(this.codeBits);
      const childLeaves = this.reader.readMbUInt();
      const payloadBits = this.reader.readMbUInt();
      if (target < consumed + childLeaves) {
        out[depth] = code;
        this.readChildren(depth + 1, childLeaves, target - consumed, out);
        return;
      }
      this.skipPayload(depth + 1, childLeaves, payloadBits);
      consumed += childLeaves;
    }
    throw new RangeError("TI00 child index not found");
  }

  readLeafBlocksByCount(blocks, target, out) {
    for (let block = 0; block < blocks; block++) {
      const leaves = this.reader.readMbUInt();
      if (target < leaves) {
        this.reader.skipBits(target * this.codeBits);
        out[this.maxDepth - 1] = this.reader.readBitsAsInt32(this.codeBits);
        return;
      }
      this.reader.skipBits(leaves * this.codeBits);
      target -= leaves;
    }
    throw new RangeError("TI00 leaf index not found");
  }

  readLeafBlocksByLeafCount(leaves, target, out) {
    let consumed = 0;
    while (consumed < leaves) {
      const blockLeaves = this.reader.readMbUInt();
      if (target < consumed + blockLeaves) {
        this.reader.skipBits((target - consumed) * this.codeBits);
        out[this.maxDepth - 1] = this.reader.readBitsAsInt32(this.codeBits);
        return;
      }
      this.reader.skipBits(blockLeaves * this.codeBits);
      consumed += blockLeaves;
    }
    throw new RangeError("TI00 leaf index not found");
  }

  skipPayload(depth, leaves, payloadBits) {
    if (payloadBits > 0) this.reader.skipBits(payloadBits);
    else this.skipChildren(depth, leaves);
  }

  skipChildren(depth, leaves) {
    let consumed = 0;
    if (depth === this.maxDepth - 1) {
      while (consumed < leaves) {
        const blockLeaves = this.reader.readMbUInt();
        this.reader.skipBits(blockLeaves * this.codeBits);
        consumed += blockLeaves;
      }
      return;
    }
    while (consumed < leaves) {
      this.reader.readBitsAsInt32(this.codeBits);
      const childLeaves = this.reader.readMbUInt();
      const payloadBits = this.reader.readMbUInt();
      this.skipPayload(depth + 1, childLeaves, payloadBits);
      consumed += childLeaves;
    }
  }
}

function readChunkLayout(factory, sourceSize) {
  return withReader(factory, 0, (reader) => CHUNK_NAMES.map((expected) => {
    const name = readAscii(reader, 4);
    const size = reader.readMbUInt();
    if (name !== expected) throw new Error(`GisWordBook expected ${expected}, got ${name}`);
    const chunk = { name, dataStart: reader.pos, size };
    if (chunk.dataStart + size > sourceSize) throw new Error("chunk data exceeds source size");
    reader.skipInByte(size);
    return chunk;
  }).map((chunk, index, chunks) => {
    if (index === chunks.length - 1 && reader.pos !== sourceSize) {
      throw new Error("GisWordBook has trailing bytes");
    }
    return chunk;
  }));
}

function readHeader(reader, size) {
  const start = reader.pos;
  const version = readBStrAscii(reader, 16);
  if (version !== VERSION) throw new Error(`invalid GisWordBook version: ${version}`);
  const metadataSize = reader.readMbUInt();
  const metadata = metadataSize === 0 ? null : textDecoder.decode(reader.readAsBytes(metadataSize));
  if (reader.pos - start !== size) throw new Error("GW00 has trailing bytes");
  return { version, metadata };
}

function decodeTargets(reader, pageRecordCount, targets, tokenBits) {
  const packetCount = reader.readMbUInt();
  const palette = new Array(PALETTE_SIZE + 1).fill(null);
  const results = new Map();
  let current = [];
  let recordIndex = 0;
  let targetPos = 0;
  let target = targets[targetPos];
  for (let packet = 0; packet < packetCount; packet++) {
    const type = reader.readBitsAsInt32(2);
    const valueBits = reader.readMbUInt();
    if (type === 0) {
      const start = bitPosition(reader);
      const slots = reader.readBitsAsInt32(15);
      palette.fill(null);
      for (let bit = 0; bit < PALETTE_SIZE; bit++) {
        if ((slots & (1 << bit)) !== 0) palette[bit + 1] = reader.readBitsAsInt32(tokenBits);
      }
      assertConsumedBits(reader, start, valueBits);
    } else if (type === 1) {
      const start = bitPosition(reader);
      const slot = reader.readBitsAsInt32(4);
      if (slot === 0) throw new Error("TT00 palette slot must be non-zero");
      palette[slot] = reader.readBitsAsInt32(tokenBits);
      assertConsumedBits(reader, start, valueBits);
    } else if (type === 2) {
      if (valueBits % 4 !== 0) throw new Error("invalid TT00 token payload size");
      for (let index = 0; index < valueBits / 4; index++) {
        const localCode = reader.readBitsAsInt32(4);
        if (localCode === 0) {
          if (recordIndex === target) {
            results.set(target, current);
            current = [];
            targetPos++;
            if (targetPos === targets.length) return results;
            target = targets[targetPos];
          }
          recordIndex++;
        } else if (recordIndex === target) {
          const tokenId = palette[localCode];
          if (tokenId === null) throw new Error("TT00 references empty palette slot");
          current.push(tokenId);
        }
      }
    } else {
      reader.skipBits(valueBits);
    }
  }
  throw new Error("TT00 target record terminator not found");
}

function validateTokenPage(tokenSize, count, streamSize, previous) {
  if (tokenSize < previous || tokenSize <= 0 || count <= 0 || streamSize !== tokenSize * count) {
    throw new Error("invalid TM00 token page");
  }
}

function validateTextPage(tokenCount, recordCount, previous) {
  if (tokenCount < previous || recordCount <= 0) throw new Error("invalid TT00 record page");
}

function validateIndexHeader(depth, records, bits, roots, streamSize) {
  if (depth <= 0 || records <= 0 || bits < 1 || bits > 31 || roots <= 0 || streamSize <= 0) {
    throw new Error("invalid TI00 header");
  }
}

function requiredBits(count) { return count <= 1 ? 1 : Math.ceil(Math.log2(count)); }
function bitPosition(reader) { return reader.pos * 8 - reader.getBitOffset(); }

function assertConsumedBits(reader, start, expected) {
  if (bitPosition(reader) - start !== expected) throw new Error("TT00 packet size mismatch");
}

function readAscii(reader, length) {
  let result = "";
  for (const byte of reader.readAsBytes(length)) result += String.fromCharCode(byte);
  return result;
}

function readBStrAscii(reader, length) {
  const bytes = reader.readAsBytes(length);
  const zero = bytes.indexOf(0);
  const end = zero < 0 ? bytes.length : zero;
  let result = "";
  for (let index = 0; index < end; index++) result += String.fromCharCode(bytes[index]);
  return result;
}

function concatBytes(chunks) {
  const length = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const result = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.length;
  }
  return result;
}

function withReader(factory, offset, callback) {
  const reader = factory.create(offset);
  try {
    return callback(reader);
  } finally {
    reader.close();
  }
}
