import { RgbaImage } from "./RgbaImage.js";
import {
  Color,
  MapEdgeRenderOptions,
  MapFillRenderOptions,
  MapImageRenderOptions,
} from "./types.js";

export class MapFillRenderer {
  get defaultOptions() {
    return new MapFillRenderOptions();
  }

  render(reader, selector, options = null) {
    return this.renderRaster(
      selector.readRaster(reader),
      options ?? this.defaultOptions,
    );
  }

  renderRaster(raster, options = null) {
    const effectiveOptions = options ?? this.defaultOptions;
    const image = new RgbaImage(raster.width, raster.height);
    const defaultColor = normalizeColor(effectiveOptions.defaultColor);
    const colors = normalizeColorMap(effectiveOptions.colors);
    const colorResolver = effectiveOptions.colorResolver;
    let offset = 0;
    for (let imageY = 0; imageY < raster.height; imageY += 1) {
      const rasterY = raster.height - imageY - 1;
      for (let rasterX = 0; rasterX < raster.width; rasterX += 1) {
        const value = raster.get(rasterX, rasterY);
        const color = colors.get(value)
          ?? resolveDynamicColor(colorResolver, value, rasterX, rasterY)
          ?? defaultColor;
        image.data[offset] = color[0];
        image.data[offset + 1] = color[1];
        image.data[offset + 2] = color[2];
        image.data[offset + 3] = color[3];
        offset += 4;
      }
    }
    return image;
  }
}

export class MapEdgeRenderer {
  get defaultOptions() {
    return new MapEdgeRenderOptions();
  }

  render(reader, selector, options = null) {
    return this.renderRaster(
      selector.readRaster(reader),
      options ?? this.defaultOptions,
    );
  }

  renderRaster(raster, options = null) {
    const effectiveOptions = options ?? this.defaultOptions;
    const edgeColor = normalizeColor(effectiveOptions.edgeColor);
    const backgroundColor = normalizeColor(effectiveOptions.backgroundColor);
    const edgeWidth = validateEdgeWidth(effectiveOptions.edgeWidth);
    let edgePixels = new Set();
    for (let imageY = 0; imageY < raster.height; imageY += 1) {
      const rasterY = raster.height - imageY - 1;
      for (let rasterX = 0; rasterX < raster.width; rasterX += 1) {
        if (isBoundaryPixel(raster, rasterX, rasterY, effectiveOptions.includeZero)) {
          edgePixels.add(pixelKey(rasterX, imageY, raster.width));
        }
      }
    }
    if (edgeWidth > 1) {
      edgePixels = expandImagePixels(
        edgePixels,
        raster.width,
        raster.height,
        edgeWidth,
      );
    }
    const image = new RgbaImage(raster.width, raster.height);
    let offset = 0;
    for (let imageY = 0; imageY < raster.height; imageY += 1) {
      for (let rasterX = 0; rasterX < raster.width; rasterX += 1) {
        const color = edgePixels.has(pixelKey(rasterX, imageY, raster.width))
          ? edgeColor
          : backgroundColor;
        image.data[offset] = color[0];
        image.data[offset + 1] = color[1];
        image.data[offset + 2] = color[2];
        image.data[offset + 3] = color[3];
        offset += 4;
      }
    }
    return image;
  }
}

export class MapImageRenderer {
  constructor({
    fillRenderer = new MapFillRenderer(),
    edgeRenderer = new MapEdgeRenderer(),
  } = {}) {
    this.fillRenderer = fillRenderer;
    this.edgeRenderer = edgeRenderer;
  }

  get defaultOptions() {
    return new MapImageRenderOptions();
  }

  render(reader, selector, options = null) {
    const effectiveOptions = options ?? this.defaultOptions;
    return this.renderRaster(selector.readRaster(reader), effectiveOptions);
  }

  renderRaster(raster, options = null) {
    const effectiveOptions = options ?? this.defaultOptions;
    const fill = this.fillRenderer.renderRaster(raster, effectiveOptions.fillOptions);
    if (effectiveOptions.edgeOptions === null) {
      return fill;
    }
    const edge = this.edgeRenderer.renderRaster(raster, effectiveOptions.edgeOptions);
    return alphaComposite(fill, edge);
  }
}

export class FastMapImageRenderer {
  constructor({
    fallback = new MapImageRenderer(),
  } = {}) {
    this.fallback = fallback;
  }

  get defaultOptions() {
    return this.fallback.defaultOptions;
  }

  render(reader, selector, options = null) {
    return this.renderRaster(selector.readRaster(reader), options);
  }

  renderRaster(raster, options = null) {
    const effectiveOptions = options ?? this.defaultOptions;
    const edgeOptions = effectiveOptions.edgeOptions;
    if (!canRenderFast(effectiveOptions)) {
      return this.fallback.renderRaster(raster, effectiveOptions);
    }
    const fillOptions = effectiveOptions.fillOptions;
    const defaultColor = normalizeColor(fillOptions.defaultColor);
    const colors = normalizeColorMap(fillOptions.colors);
    const zeroColor = colors.get(0) ?? defaultColor;
    const selectedEntry = firstNonZeroColor(colors);
    const selectedCode = selectedEntry === null ? null : selectedEntry.code;
    const selectedColor = selectedEntry === null ? null : selectedEntry.color;
    const edgeColor = edgeOptions === null ? null : normalizeColor(edgeOptions.edgeColor);
    const image = new RgbaImage(raster.width, raster.height);
    const sourceData = raster.data;
    const imageData = image.data;
    let offset = 0;
    for (let imageY = 0; imageY < raster.height; imageY += 1) {
      const rasterY = raster.height - imageY - 1;
      const rowOffset = rasterY * raster.width;
      for (let rasterX = 0; rasterX < raster.width; rasterX += 1) {
        const value = sourceData[rowOffset + rasterX];
        const color = edgeColor !== null
          && isBoundaryDataPixel(sourceData, raster.width, raster.height, rasterX, rasterY, edgeOptions.includeZero)
          ? edgeColor
          : value === selectedCode
            ? selectedColor
            : value === 0
              ? zeroColor
              : defaultColor;
        imageData[offset] = color[0];
        imageData[offset + 1] = color[1];
        imageData[offset + 2] = color[2];
        imageData[offset + 3] = color[3];
        offset += 4;
      }
    }
    return image;
  }
}

export function defaultColorForValue(value) {
  if (value === 0) {
    return new Color(0, 56, 180, 255);
  }
  let hash = value >>> 0;
  hash ^= hash << 13;
  hash ^= hash >>> 17;
  hash ^= hash << 5;
  const hue = ((hash >>> 0) % 360) / 60;
  const chroma = 0.42;
  const x = chroma * (1 - Math.abs((hue % 2) - 1));
  let red = 0;
  let green = 0;
  let blue = 0;
  if (hue < 1) {
    red = chroma;
    green = x;
  } else if (hue < 2) {
    red = x;
    green = chroma;
  } else if (hue < 3) {
    green = chroma;
    blue = x;
  } else if (hue < 4) {
    green = x;
    blue = chroma;
  } else if (hue < 5) {
    red = x;
    blue = chroma;
  } else {
    red = chroma;
    blue = x;
  }
  const match = 0.55;
  return new Color(
    Math.round((red + match) * 255),
    Math.round((green + match) * 255),
    Math.round((blue + match) * 255),
    255,
  );
}

function canRenderFast(options) {
  if (options.fillOptions.colorResolver !== null && options.fillOptions.colorResolver !== undefined) {
    return false;
  }
  if (options.edgeOptions === null) {
    return true;
  }
  if (options.edgeOptions.edgeWidth !== 1) {
    return false;
  }
  return normalizeColor(options.edgeOptions.edgeColor)[3] === 255;
}

function firstNonZeroColor(colors) {
  for (const [code, color] of colors.entries()) {
    if (code !== 0) {
      return { code, color };
    }
  }
  return null;
}

function isBoundaryDataPixel(data, width, height, x, y, includeZero) {
  const value = data[x + y * width];
  if (x + 1 < width) {
    const neighborValue = data[x + 1 + y * width];
    if (neighborValue !== value && (includeZero || (value !== 0 && neighborValue !== 0))) {
      return true;
    }
  }
  if (y + 1 < height) {
    const neighborValue = data[x + (y + 1) * width];
    if (neighborValue !== value && (includeZero || (value !== 0 && neighborValue !== 0))) {
      return true;
    }
  }
  return false;
}

export function alphaComposite(base, overlay) {
  if (base.width !== overlay.width || base.height !== overlay.height) {
    throw new RangeError("base and overlay image sizes must match");
  }
  const result = new RgbaImage(base.width, base.height);
  for (let offset = 0; offset < base.data.length; offset += 4) {
    const overlayAlpha = overlay.data[offset + 3] / 255;
    const baseAlpha = base.data[offset + 3] / 255;
    const outAlpha = overlayAlpha + baseAlpha * (1 - overlayAlpha);
    if (outAlpha === 0) {
      result.data[offset] = 0;
      result.data[offset + 1] = 0;
      result.data[offset + 2] = 0;
      result.data[offset + 3] = 0;
      continue;
    }
    result.data[offset] = compositeComponent(
      base.data[offset],
      baseAlpha,
      overlay.data[offset],
      overlayAlpha,
      outAlpha,
    );
    result.data[offset + 1] = compositeComponent(
      base.data[offset + 1],
      baseAlpha,
      overlay.data[offset + 1],
      overlayAlpha,
      outAlpha,
    );
    result.data[offset + 2] = compositeComponent(
      base.data[offset + 2],
      baseAlpha,
      overlay.data[offset + 2],
      overlayAlpha,
      outAlpha,
    );
    result.data[offset + 3] = Math.round(outAlpha * 255);
  }
  return result;
}

export function isBoundaryPixel(raster, rasterX, rasterY, includeZero = false) {
  const value = raster.get(rasterX, rasterY);
  for (const [neighborX, neighborY] of [
    [rasterX + 1, rasterY],
    [rasterX, rasterY + 1],
  ]) {
    if (neighborX >= raster.width || neighborY >= raster.height) {
      continue;
    }
    const neighborValue = raster.get(neighborX, neighborY);
    if (neighborValue === value) {
      continue;
    }
    if (includeZero || (value !== 0 && neighborValue !== 0)) {
      return true;
    }
  }
  return false;
}

export function normalizeColor(color) {
  let values;
  if (Array.isArray(color) || color instanceof Uint8ClampedArray || color instanceof Uint8Array) {
    values = color;
  } else if (color !== null && typeof color === "object") {
    values = [color.r, color.g, color.b, color.a ?? 255];
  } else {
    throw new TypeError("color must be an array or an object");
  }
  if (values.length < 3) {
    throw new RangeError("color must have at least RGB components");
  }
  const result = [
    values[0],
    values[1],
    values[2],
    values.length >= 4 ? values[3] : 255,
  ];
  for (const component of result) {
    if (!Number.isInteger(component) || component < 0 || component > 255) {
      throw new RangeError("color components must be integers in 0..255");
    }
  }
  return result;
}

function resolveDynamicColor(colorResolver, value, rasterX, rasterY) {
  if (colorResolver === null || colorResolver === undefined) {
    return null;
  }
  if (typeof colorResolver !== "function") {
    throw new TypeError("colorResolver must be a function");
  }
  const color = colorResolver(value, rasterX, rasterY);
  return color === null || color === undefined ? null : normalizeColor(color);
}

function compositeComponent(base, baseAlpha, overlay, overlayAlpha, outAlpha) {
  return Math.round(
    (overlay * overlayAlpha + base * baseAlpha * (1 - overlayAlpha)) / outAlpha,
  );
}

function normalizeColorMap(colors) {
  if (colors instanceof Map) {
    const result = new Map();
    for (const [value, color] of colors.entries()) {
      result.set(Number(value), normalizeColor(color));
    }
    return result;
  }
  const result = new Map();
  for (const [value, color] of Object.entries(colors ?? {})) {
    result.set(Number(value), normalizeColor(color));
  }
  return result;
}

function validateEdgeWidth(edgeWidth) {
  if (!Number.isInteger(edgeWidth) || edgeWidth < 1) {
    throw new RangeError("edgeWidth must be an integer greater than or equal to 1");
  }
  return edgeWidth;
}

function expandImagePixels(pixels, width, height, edgeWidth) {
  const left = Math.floor((edgeWidth - 1) / 2);
  const right = Math.floor(edgeWidth / 2);
  const expanded = new Set();
  for (const key of pixels) {
    const x = key % width;
    const y = Math.floor(key / width);
    for (let dy = -left; dy <= right; dy += 1) {
      const targetY = y + dy;
      if (targetY < 0 || targetY >= height) {
        continue;
      }
      for (let dx = -left; dx <= right; dx += 1) {
        const targetX = x + dx;
        if (targetX < 0 || targetX >= width) {
          continue;
        }
        expanded.add(pixelKey(targetX, targetY, width));
      }
    }
  }
  return expanded;
}

function pixelKey(x, y, width) {
  return x + y * width;
}
