import {
  formatRenderStats,
  GaluchatMapView,
} from "./GaluchatMapView.js";

const DEFAULT_CONTROLS = Object.freeze({
  zoomButtons: false,
  status: true,
  crosshair: true,
});

export class GaluchatInteractiveMap extends EventTarget {
  constructor(element, source, options = {}) {
    super();
    if (element == null) {
      throw new TypeError("element is required");
    }
    this.element = element;
    this.controls = { ...DEFAULT_CONTROLS, ...(options.controls ?? {}) };
    this.canvas = options.canvas ?? this.createCanvas();
    this.statusElement = this.controls.status
      ? options.statusElement ?? this.createStatusElement()
      : null;
    this.crosshairElement = this.controls.crosshair
      ? options.crosshairElement ?? this.createCrosshairElement()
      : null;
    this.controlsElement = this.controls.zoomButtons
      ? options.controlsElement ?? this.createControlsElement()
      : null;
    this.zoomInButton = this.controlsElement?.querySelector("[data-galuchat-zoom-in]") ?? null;
    this.zoomOutButton = this.controlsElement?.querySelector("[data-galuchat-zoom-out]") ?? null;
    this.installElements(options);
    this.mapView = new GaluchatMapView(this.canvas, source, {
      center: options.center,
      selectedCode: options.selectedCode,
      style: options.style,
      maxWidth: options.maxWidth,
      maxHeight: options.maxHeight,
      minDragPixels: options.minDragPixels,
      interaction: options.interaction ?? {
        dragPan: true,
        wheelZoom: false,
        clickSelect: true,
        hoverStatus: true,
      },
    });
    this.bindControls();
    this.forwardEvents();
  }

  createCanvas() {
    const canvas = document.createElement("canvas");
    canvas.className = "galuchat-interactive-map-canvas";
    canvas.width = 640;
    canvas.height = 480;
    canvas.setAttribute("aria-label", "interactive map");
    return canvas;
  }

  createStatusElement() {
    const element = document.createElement("div");
    element.className = "galuchat-interactive-map-status";
    element.textContent = "loading...";
    return element;
  }

  createCrosshairElement() {
    const element = document.createElement("div");
    element.className = "galuchat-interactive-map-crosshair";
    element.setAttribute("aria-hidden", "true");
    return element;
  }

  createControlsElement() {
    const element = document.createElement("div");
    element.className = "galuchat-interactive-map-controls";
    const zoomIn = document.createElement("button");
    zoomIn.type = "button";
    zoomIn.className = "galuchat-interactive-map-control";
    zoomIn.dataset.galuchatZoomIn = "";
    zoomIn.setAttribute("aria-label", "zoom in");
    zoomIn.textContent = "+";
    const zoomOut = document.createElement("button");
    zoomOut.type = "button";
    zoomOut.className = "galuchat-interactive-map-control";
    zoomOut.dataset.galuchatZoomOut = "";
    zoomOut.setAttribute("aria-label", "zoom out");
    zoomOut.textContent = "-";
    element.append(zoomIn, zoomOut);
    return element;
  }

  installElements(options) {
    if (options.canvas == null) {
      this.element.appendChild(this.canvas);
    }
    if (this.crosshairElement !== null && options.crosshairElement === undefined) {
      this.element.appendChild(this.crosshairElement);
    }
    if (this.statusElement !== null && options.statusElement === undefined) {
      this.element.appendChild(this.statusElement);
    }
    if (this.controlsElement !== null && options.controlsElement === undefined) {
      this.element.appendChild(this.controlsElement);
    }
  }

  bindControls() {
    this.zoomInButton?.addEventListener("click", () => this.zoomIn());
    this.zoomOutButton?.addEventListener("click", () => this.zoomOut());
  }

  forwardEvents() {
    for (const type of ["maprender", "viewchange", "zoomchange", "select", "placechange", "pointerplace"]) {
      this.mapView.addEventListener(type, (event) => {
        if (type === "maprender") {
          this.updateStatus(this.mapView.center.lon, this.mapView.center.lat);
          this.updateControls();
        } else if (type === "pointerplace") {
          this.updateStatus(event.detail.lon, event.detail.lat, event.detail);
        } else if (type === "zoomchange") {
          this.updateControls();
        }
        this.dispatchEvent(new CustomEvent(type, { detail: event.detail }));
      });
    }
  }

  render() {
    this.setStatusText("rendering...");
    return this.mapView.render();
  }

  setView(options = {}) {
    return this.mapView.setView(options);
  }

  setCenter(center) {
    return this.mapView.setCenter(center);
  }

  setSelectedCode(selectedCode) {
    return this.mapView.setSelectedCode(selectedCode);
  }

  setStyle(style) {
    return this.mapView.setStyle(style);
  }

  getZoomLevelIndex() {
    return this.mapView.getZoomLevelIndex();
  }

  getZoomLevelCount() {
    return this.mapView.getZoomLevelCount();
  }

  canZoomIn() {
    return this.mapView.canZoomIn();
  }

  canZoomOut() {
    return this.mapView.canZoomOut();
  }

  zoomIn(anchorPoint = this.mapView.canvasCenterPoint()) {
    return this.mapView.zoomIn(anchorPoint);
  }

  zoomOut(anchorPoint = this.mapView.canvasCenterPoint()) {
    return this.mapView.zoomOut(anchorPoint);
  }

  zoomByWheel(event) {
    if (event.deltaY === 0) {
      return null;
    }
    event.preventDefault();
    const anchorPoint = this.mapView.eventToCanvasPoint(event);
    return event.deltaY > 0
      ? this.zoomOut(anchorPoint)
      : this.zoomIn(anchorPoint);
  }

  setZoomLevel(index, anchorPoint = this.mapView.canvasCenterPoint()) {
    return this.mapView.setZoomLevel(index, anchorPoint);
  }

  clearSelection() {
    return this.mapView.clearSelection();
  }

  dispose() {
    this.mapView.dispose();
  }

  get source() {
    return this.mapView.source;
  }

  get center() {
    return this.mapView.center;
  }

  get selectedCode() {
    return this.mapView.selectedCode;
  }

  get currentRect() {
    return this.mapView.currentRect;
  }

  get currentPixelScale() {
    return this.mapView.currentPixelScale;
  }

  get currentImageData() {
    return this.mapView.currentImageData;
  }

  get currentPlace() {
    return this.mapView.currentPlace;
  }

  get lastRenderStats() {
    return this.mapView.lastRenderStats;
  }

  updateStatus(lon, lat, place = null) {
    const resolvedPlace = place ?? this.source.resolvePlaceAt(lon, lat);
    const firstLine = `${lon.toFixed(6)}, ${lat.toFixed(6)}  ${resolvedPlace.name}`;
    const statsLine = formatRenderStats(this.lastRenderStats);
    this.setStatusText(statsLine === null ? firstLine : `${firstLine}\n${statsLine}`);
  }

  setStatusText(text) {
    if (this.statusElement !== null) {
      this.statusElement.textContent = text;
    }
  }

  updateControls() {
    let canZoomIn = false;
    let canZoomOut = false;
    try {
      canZoomIn = this.canZoomIn();
      canZoomOut = this.canZoomOut();
    } catch {
      canZoomIn = false;
      canZoomOut = false;
    }
    if (this.zoomInButton !== null) {
      this.zoomInButton.disabled = !canZoomIn;
    }
    if (this.zoomOutButton !== null) {
      this.zoomOutButton.disabled = !canZoomOut;
    }
  }
}
