import {
  RLE_PALLET_2,
  RLE_PALLET_3,
  RLE_PALLET_5,
  RLE_PALLET_16,
} from "./CellHeader.js";

export class PalletHeader {
  constructor(palletMode, capacity, updatePalletTable, initialIndex, valueBitsAdd) {
    this.palletMode = palletMode;
    this.capacity = capacity;
    this.updatePalletTable = updatePalletTable;
    this.initialIndex = initialIndex;
    this.valueBitsAdd = valueBitsAdd;
  }

  static readFrom(reader, palletMode) {
    if (palletMode === RLE_PALLET_2) {
      const bits = reader.readBitsAsInt32(7);
      return new PalletHeader(palletMode, 2, (bits >> 4) & 0x03, bits >> 6, bits & 0x0f);
    }
    if (palletMode === RLE_PALLET_3) {
      const bits = reader.readBitsAsInt32(9);
      return new PalletHeader(palletMode, 3, (bits >> 4) & 0x07, bits >> 7, bits & 0x0f);
    }
    if (palletMode === RLE_PALLET_5) {
      const bits = reader.readBitsAsInt32(12);
      return new PalletHeader(palletMode, 5, (bits >> 4) & 0x1f, bits >> 9, bits & 0x0f);
    }
    if (palletMode === RLE_PALLET_16) {
      const bits = reader.readBitsAsInt32(20);
      return new PalletHeader(palletMode, 16, bits >> 4, null, bits & 0x0f);
    }
    throw new Error("invalid RLE pallet mode");
  }
}
