export class RgbaImage {
  constructor(width, height, data = null) {
    if (!Number.isInteger(width) || width < 0 || !Number.isInteger(height) || height < 0) {
      throw new RangeError("invalid image size");
    }
    this.width = width;
    this.height = height;
    const expectedLength = width * height * 4;
    this.data = data === null ? new Uint8ClampedArray(expectedLength) : toUint8ClampedArray(data);
    if (this.data.length !== expectedLength) {
      throw new RangeError("RGBA image data size mismatch");
    }
  }

  toImageData(imageDataFactory = null) {
    if (typeof imageDataFactory === "function") {
      const imageData = imageDataFactory(this.width, this.height);
      imageData.data.set(this.data);
      return imageData;
    }
    if (typeof ImageData !== "undefined") {
      return new ImageData(new Uint8ClampedArray(this.data), this.width, this.height);
    }
    throw new Error("ImageData is not available; pass an imageDataFactory");
  }
}

function toUint8ClampedArray(data) {
  if (data instanceof Uint8ClampedArray) {
    return data;
  }
  return new Uint8ClampedArray(data);
}
