import { BytesReader } from "../../io/BytesReader.js";

const CHUNK_NAME = "GLCH";
const VERSION = "WGSMap/3";

export class WGSMapHeader {
  constructor(reader) {
    if (readAscii(reader, 4) !== CHUNK_NAME) {
      throw new Error("invalid WGSMap header chunk name");
    }
    const size = reader.readMbUInt();
    const payload = new BytesReader(reader.bytes, reader.pos, size);
    reader.skipInByte(size);

    this.version = payload.readBStrAscii(16);
    if (this.version !== VERSION) {
      throw new Error(`invalid WGSMap/3 version: ${this.version}`);
    }
    this.unitInvX = payload.readMbUInt();
    this.unitInvY = payload.readMbUInt();
    this.west = payload.readMbInt();
    this.south = payload.readMbInt();
    const metadataLength = payload.readMbUInt();
    this.metadata = metadataLength === 0 ? null : new TextDecoder().decode(payload.readAsBytes(metadataLength));
  }

  static unpack(reader) {
    return new WGSMapHeader(reader);
  }

  isVersion3() {
    return this.version === VERSION;
  }
}

function readAscii(reader, length) {
  const bytes = reader.readAsBytes(length);
  let text = "";
  for (let i = 0; i < bytes.length; i++) {
    text += String.fromCharCode(bytes[i]);
  }
  return text;
}
