import { BytesReader } from "./BytesReader.js";

/** Creates an independent forward reader at an absolute byte offset. */
export class BytesReaderFactory {
  constructor(bytes) {
    if (!(bytes instanceof Uint8Array)) {
      throw new TypeError("BytesReaderFactory requires Uint8Array");
    }
    this.bytes = bytes;
  }

  create(offset = 0) {
    return new BytesReader(this.bytes, offset);
  }
}
